svg.script:
(() => {
  const svg = document.getElementById('doc-root');
  const hud = document.getElementById('hud');
  const indicator = document.getElementById('hud-indicator');
  const zoomLabel = document.getElementById('hud-zoom-label');
  const btnPrev = document.getElementById('btn-prev');
  const btnNext = document.getElementById('btn-next');
  const btnZoomOut = document.getElementById('btn-zoom-out');
  const btnZoomReset = document.getElementById('btn-zoom-reset');
  const btnZoomIn = document.getElementById('btn-zoom-in');

  const TOTAL_PAGES = 4;
  const VIEW_W      = 242.0000;
  const VIEW_H      = 337.0000;
  const STRIDE_X    = 278.0000;
  const DURATION_MS = 380;
  const MIN_ZOOM    = 0.5;
  const MAX_ZOOM    = 4.0;
  const ZOOM_STEP   = 0.25;

  let currentPage = 0;
  let currentX    = 0;
  let zoom        = 1.0;
  let panX        = 0.0;
  let panY        = 0.0;
  let animId      = null;
  let wheelLock   = false;
  let isDragging  = false;
  let hasDragged  = false;
  let dragStartX  = 0.0;
  let dragStartY  = 0.0;
  let dragPanX0   = 0.0;
  let dragPanY0   = 0.0;

  function clampPan() {
    if (zoom <= 1.0) {
      panX = 0.0;
      panY = 0.0;
      return;
    }
    const vw = VIEW_W / zoom;
    const vh = VIEW_H / zoom;
    const maxPanX = (VIEW_W - vw) * 0.5;
    const maxPanY = (VIEW_H - vh) * 0.5;
    panX = Math.max(-maxPanX, Math.min(maxPanX, panX));
    panY = Math.max(-maxPanY, Math.min(maxPanY, panY));
  }

  function applyViewport(x) {
    currentX = x;
    clampPan();
    const vw = VIEW_W / zoom;
    const vh = VIEW_H / zoom;
    const vx = x + (VIEW_W - vw) * 0.5 + panX;
    const vy = (VIEW_H - vh) * 0.5 + panY;
    svg.setAttribute('viewBox', `${vx.toFixed(3)} ${vy.toFixed(3)} ${vw.toFixed(3)} ${vh.toFixed(3)}`);
    hud.setAttribute('transform', `translate(${vx.toFixed(3)}, ${vy.toFixed(3)}) scale(${(1 / zoom).toFixed(5)})`);
  }

  function syncHudState() {
    indicator.textContent = `P\u00e1g. ${currentPage + 1} / ${TOTAL_PAGES}`;
    zoomLabel.textContent = `${Math.round(zoom * 100)}%`;
    btnPrev.classList.toggle('hud-btn-disabled', currentPage <= 0);
    btnNext.classList.toggle('hud-btn-disabled', currentPage >= TOTAL_PAGES - 1);
    btnZoomOut.classList.toggle('hud-btn-disabled', zoom <= MIN_ZOOM + 0.001);
    btnZoomIn.classList.toggle('hud-btn-disabled', zoom >= MAX_ZOOM - 0.001);
    svg.style.cursor = zoom > 1.0 ? (isDragging ? 'grabbing' : 'grab') : 'default';
  }

  function setZoom(nextZoom, clientX = null, clientY = null) {
    const clamped = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, Math.round(nextZoom * 100) / 100));
    if (Math.abs(clamped - zoom) < 0.001) return;
    if (clientX !== null && clientY !== null) {
      const rect = svg.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) {
        const normX = ((clientX - rect.left) / rect.width) - 0.5;
        const normY = ((clientY - rect.top) / rect.height) - 0.5;
        const ptX = panX + normX * (VIEW_W / zoom);
        const ptY = panY + normY * (VIEW_H / zoom);
        panX = ptX - normX * (VIEW_W / clamped);
        panY = ptY - normY * (VIEW_H / clamped);
      }
    }
    zoom = clamped;
    syncHudState();
    applyViewport(currentX);
  }

  function goToPage(targetIdx, immediate = false, updateHash = true) {
    const clamped = Math.max(0, Math.min(TOTAL_PAGES - 1, targetIdx));
    if (clamped !== currentPage) {
      panX = 0.0;
      panY = 0.0;
    }
    currentPage = clamped;
    const targetX = clamped * STRIDE_X;
    syncHudState();

    if (updateHash) {
      try { history.replaceState(null, '', `#page=${clamped + 1}`); } catch (_) {}
    }

    if (animId !== null) {
      cancelAnimationFrame(animId);
      animId = null;
    }

    if (immediate || Math.abs(targetX - currentX) < 0.05) {
      applyViewport(targetX);
      return;
    }

    const startX = currentX;
    const deltaX = targetX - startX;
    const startTime = performance.now();

    function tick(now) {
      const elapsed = now - startTime;
      const t = Math.min(1, elapsed / DURATION_MS);
      const ease = 1 - Math.pow(1 - t, 3);
      applyViewport(startX + deltaX * ease);
      if (t < 1) {
        animId = requestAnimationFrame(tick);
      } else {
        animId = null;
      }
    }
    animId = requestAnimationFrame(tick);
  }

  function findAnchorElement(rawId) {
    if (!rawId) return null;
    let clean = rawId.startsWith('#') ? rawId.substring(1) : rawId;
    if (!clean) return null;
    let el = document.getElementById(clean);
    if (el) return el;
    el = document.getElementById('dest-' + clean);
    if (el) return el;
    if (clean.startsWith('dest-')) {
      el = document.getElementById(clean.substring(5));
      if (el) return el;
    }
    if (clean.startsWith('pdest-')) {
      const sub = clean.substring(6);
      el = document.getElementById('dest-' + sub) || document.getElementById(sub);
      if (el) return el;
    }
    try {
      const decoded = decodeURIComponent(clean);
      if (decoded !== clean) {
        el = document.getElementById(decoded) || document.getElementById('dest-' + decoded);
        if (el) return el;
      }
    } catch (_) {}
    return null;
  }

  function showDestinationHighlight(targetEl) {
    if (!targetEl) return;
    const pageEl = targetEl.closest('[id^="page-"]');
    if (!pageEl) return;
    const old = svg.querySelectorAll('.tks-dest-highlight');
    old.forEach(el => el.remove());
    const x = parseFloat(targetEl.getAttribute('x')) || 0;
    const y = parseFloat(targetEl.getAttribute('y')) || 0;
    const w = parseFloat(targetEl.getAttribute('width')) || 170;
    const h = parseFloat(targetEl.getAttribute('height')) || 8;
    const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
    g.setAttribute('class', 'tks-dest-highlight');
    const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    rect.setAttribute('class', 'tks-highlight-box');
    rect.setAttribute('x', (x - 2.0).toFixed(3));
    rect.setAttribute('y', (y - 1.0).toFixed(3));
    rect.setAttribute('width', (w + 4.0).toFixed(3));
    rect.setAttribute('height', (h + 2.0).toFixed(3));
    rect.setAttribute('rx', '1.8');
    const bar = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    bar.setAttribute('class', 'tks-highlight-bar');
    bar.setAttribute('x', (x - 5.5).toFixed(3));
    bar.setAttribute('y', (y - 1.0).toFixed(3));
    bar.setAttribute('width', '2.5');
    bar.setAttribute('height', (h + 2.0).toFixed(3));
    bar.setAttribute('rx', '1.2');
    g.appendChild(rect);
    g.appendChild(bar);
    pageEl.appendChild(g);
    setTimeout(() => {
      rect.classList.add('tks-fade-out');
      bar.classList.add('tks-fade-out');
    }, 700);
    setTimeout(() => { g.remove(); }, 2300);
  }

  function navigateToDestination(hash, immediate = false, pushState = true) {
    if (!hash) return;
    const clean = hash.startsWith('#') ? hash.substring(1) : hash;
    const pageMatch = /^page[=-]?(\d+)$/i.exec(clean);
    if (pageMatch) {
      const p = parseInt(pageMatch[1], 10) - 1;
      goToPage(p, immediate, true);
      return;
    }
    const targetEl = findAnchorElement(clean);
    if (!targetEl) {
      const numOnly = parseInt(clean, 10);
      if (!isNaN(numOnly) && numOnly >= 1 && numOnly <= TOTAL_PAGES) {
        goToPage(numOnly - 1, immediate, true);
      }
      return;
    }
    const pageEl = targetEl.closest('[id^="page-"]');
    if (!pageEl) return;
    const m = /^page-(\d+)$/.exec(pageEl.id);
    const pIdx = m ? parseInt(m[1], 10) - 1 : 0;
    goToPage(pIdx, immediate, false);
    if (pushState) {
      try { history.pushState(null, '', '#' + clean); } catch (_) {}
    }
    if (zoom > 1.0) {
      const anchorY = parseFloat(targetEl.getAttribute('y')) || 0;
      const deskPadTop = 14.0000;
      const anchorDeskY = deskPadTop + anchorY;
      panY = anchorDeskY - VIEW_H * 0.5;
      clampPan();
      applyViewport(currentX);
    }
    showDestinationHighlight(targetEl);
  }

  btnPrev.addEventListener('click', () => goToPage(currentPage - 1));
  btnNext.addEventListener('click', () => goToPage(currentPage + 1));
  btnZoomOut.addEventListener('click', () => setZoom(zoom - ZOOM_STEP));
  btnZoomReset.addEventListener('click', () => { panX = 0; panY = 0; setZoom(1.0); });
  btnZoomIn.addEventListener('click', () => setZoom(zoom + ZOOM_STEP));

  svg.addEventListener('mousedown', (ev) => {
    if (zoom <= 1.0 || ev.button !== 0 || hud.contains(ev.target)) return;
    isDragging = true;
    hasDragged = false;
    dragStartX = ev.clientX;
    dragStartY = ev.clientY;
    dragPanX0  = panX;
    dragPanY0  = panY;
    syncHudState();
  });

  window.addEventListener('mousemove', (ev) => {
    if (!isDragging) return;
    const dx = ev.clientX - dragStartX;
    const dy = ev.clientY - dragStartY;
    if (Math.hypot(dx, dy) > 4) hasDragged = true;
    const rect = svg.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return;
    const scaleX = (VIEW_W / zoom) / rect.width;
    const scaleY = (VIEW_H / zoom) / rect.height;
    const scale  = Math.max(scaleX, scaleY);
    panX = dragPanX0 - dx * scale;
    panY = dragPanY0 - dy * scale;
    applyViewport(currentX);
  });

  window.addEventListener('mouseup', () => {
    if (isDragging) {
      isDragging = false;
      syncHudState();
    }
  });

  svg.addEventListener('click', (ev) => {
    if (hasDragged) {
      hasDragged = false;
      return;
    }
    const link = ev.target.closest('a');
    if (!link) return;
    const href = link.getAttribute('href') || link.getAttribute('xlink:href') || '';
    if (!href) return;
    if (href.startsWith('#')) {
      ev.preventDefault();
      ev.stopPropagation();
      navigateToDestination(href, false, true);
    }
  });

  window.addEventListener('keydown', (ev) => {
    if (ev.key === '+' || ev.key === '=') {
      ev.preventDefault();
      setZoom(zoom + ZOOM_STEP);
    } else if (ev.key === '-' || ev.key === '_') {
      ev.preventDefault();
      setZoom(zoom - ZOOM_STEP);
    } else if (ev.key === '0') {
      ev.preventDefault();
      panX = 0; panY = 0; setZoom(1.0);
    } else if (zoom > 1.0 && (ev.key === 'ArrowUp' || ev.key === 'ArrowDown')) {
      ev.preventDefault();
      panY += (ev.key === 'ArrowDown' ? 18 : -18) / zoom;
      applyViewport(currentX);
    } else if (ev.key === 'ArrowRight' || ev.key === 'PageDown' || ev.key === ' ') {
      ev.preventDefault();
      goToPage(currentPage + 1);
    } else if (ev.key === 'ArrowLeft' || ev.key === 'PageUp') {
      ev.preventDefault();
      goToPage(currentPage - 1);
    } else if (ev.key === 'Home') {
      ev.preventDefault();
      goToPage(0);
    } else if (ev.key === 'End') {
      ev.preventDefault();
      goToPage(TOTAL_PAGES - 1);
    }
  });

  window.addEventListener('wheel', (ev) => {
    if (ev.ctrlKey || ev.metaKey) {
      ev.preventDefault();
      const step = ev.deltaY < 0 ? 0.15 : -0.15;
      setZoom(zoom + step, ev.clientX, ev.clientY);
      return;
    }
    if (zoom > 1.0) {
      ev.preventDefault();
      panX += (ev.deltaX * 0.25) / zoom;
      panY += (ev.deltaY * 0.25) / zoom;
      applyViewport(currentX);
      return;
    }
    if (wheelLock) return;
    const delta = Math.abs(ev.deltaX) > Math.abs(ev.deltaY) ? ev.deltaX : ev.deltaY;
    if (Math.abs(delta) < 18) return;
    wheelLock = true;
    goToPage(currentPage + (delta > 0 ? 1 : -1));
    setTimeout(() => { wheelLock = false; }, 320);
  }, { passive: false });

  window.addEventListener('hashchange', () => {
    if (window.location.hash) {
      navigateToDestination(window.location.hash, false, false);
    }
  });

  if (window.location.hash) {
    navigateToDestination(window.location.hash, true, false);
  } else {
    goToPage(0, true, true);
  }
})();
